// Shared test helpers for the acceptance collection (TICK-331).
// Generated by docs/acceptance/guide/build/collection.py; edit it there.
// Load it in a request with:
//   const N = require('./lib/nava')({ test, expect, res, bru });
const REGISTERED = ['tenant_unresolved', 'invalid_token', 'idempotency_key_reuse', 'forbidden', 'invalid_idp_config',
  'domain_claimed', 'onboarding_conflict', 'idempotency_in_flight', 'invalid_cursor', 'rate_limited', 'not_found',
  'validation_failed', 'method_not_allowed', 'not_implemented', 'internal_error'];

const b64url = (s) => Buffer.from(s, 'base64url');

module.exports = ({ test, expect, res, bru } = {}) => {
  const N = {
    REGISTERED,
    // A runtime variable, else the environment's.
    v(name) {
      const x = bru.getVar(name);
      return x !== undefined && x !== null && x !== '' ? x : bru.getEnvVar(name);
    },
    url: (s) => bru.interpolate(s),
    header(name) {
      const h = res.getHeader(name.toLowerCase());
      return Array.isArray(h) ? h.join(', ') : h;
    },
    // The response bytes as text, exactly as received.
    text() {
      const buf = res.getDataBuffer ? res.getDataBuffer() : null;
      if (buf) return Buffer.isBuffer(buf) ? buf.toString('utf8') : Buffer.from(String(buf), 'base64').toString('utf8');
      const b = res.getBody();
      return typeof b === 'string' ? b : JSON.stringify(b);
    },
    json() {
      const b = res.getBody();
      return typeof b === 'string' ? JSON.parse(b) : b;
    },
    status(code) {
      test(`HTTP ${code}`, () => expect(res.getStatus()).to.eql(code));
    },
    // RFC 9457 problem body as api/errors.yaml registers it.
    problem(code, status) {
      test(`HTTP ${status}`, () => expect(res.getStatus()).to.eql(status));
      test(`problem+json, code ${code}`, () => {
        expect(N.header('Content-Type') || '').to.include('application/problem+json');
        const b = N.json();
        expect(b).to.include.all.keys('type', 'title', 'status', 'code', 'detail', 'instance');
        expect(b.code).to.eql(code);
        expect(b.status).to.eql(status);
        expect(b.type).to.eql('urn:nava:problem:' + code);
        expect(REGISTERED).to.include(b.code);
      });
      test("problem instance is this response's X-Request-Id", () => {
        const id = N.header('X-Request-Id');
        expect(id, 'X-Request-Id header').to.be.a('string').and.not.empty;
        expect(N.json().instance).to.eql('urn:nava:request:' + id);
      });
    },
    // validation_failed and invalid_idp_config: errors[] points at the field.
    fieldError(pointer) {
      test(`errors[] points at ${pointer}`, () => {
        const errs = N.json().errors || [];
        expect(errs.map(e => e.pointer)).to.include(pointer);
      });
    },
    // Decodes a JWT payload (no verification: the server does that).
    jwt(t) {
      return JSON.parse(b64url(String(t).split('.')[1]).toString('utf8'));
    },
    // A JWT with its payload replaced; the signature no longer matches.
    rewrite(t, change) {
      const [h, p, s] = String(t).split('.');
      const claims = JSON.parse(b64url(p).toString('utf8'));
      change(claims);
      return [h, Buffer.from(JSON.stringify(claims)).toString('base64url'), s].join('.');
    },
    // The response text never names the other tenant.
    noLeak(...needles) {
      test('response names nothing of the other tenant', () => {
        const text = N.text();
        needles.filter(Boolean).forEach(n => expect(text).to.not.include(n));
      });
    },
    me(tenant) {
      test('HTTP 200', () => expect(res.getStatus()).to.eql(200));
      test(`tenant_id is ${tenant}`, () => expect(N.json().tenant_id).to.eql(tenant));
      test('Me has the contract fields', () => {
        const b = N.json();
        expect(b).to.include.all.keys('user_id', 'tenant_id', 'groups', 'idp_alias', 'group_paths');
        expect(b.groups).to.be.an('array');
        expect(b.group_paths).to.be.an('array');
        b.group_paths.forEach(g => {
          expect(g.path, 'path relative to the tenant root').to.match(/^\//).and.not.include('/t/');
          expect(b.groups).to.include(g.id);
        });
      });
    },
    paths() { return N.json().group_paths.map(g => g.path); },
    form(o) {
      return Object.entries(o).map(([k, x]) => encodeURIComponent(k) + '=' + encodeURIComponent(x)).join('&');
    },
    // bru.sendRequest, with a 4xx/5xx returned instead of thrown.
    async send(opts) {
      try {
        return await bru.sendRequest(opts);
      } catch (e) {
        if (e && e.response) return e.response;
        throw e;
      }
    },
    // A password-grant token from the nava realm (or another realm).
    async token(user, password, { client = 'nava-web', scope = 'openid', realm = N.v('realm') } = {}) {
      return N.send({
        url: N.url(`{{keycloak_url}}/realms/${realm}/protocol/openid-connect/token`),
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        data: N.form({ grant_type: 'password', client_id: client, scope, username: user, password }),
      });
    },
    // A Keycloak master-realm admin token in kc_admin_token. It lives 60 s, so
    // every admin call fetches a fresh one.
    async kcAdmin() {
      const r = await N.token(N.v('kc_admin_user'), N.v('kc_admin_password'), { client: 'admin-cli', scope: 'openid', realm: 'master' });
      if (r.status !== 200) throw new Error('Keycloak admin token failed: HTTP ' + r.status);
      bru.setVar('kc_admin_token', r.data.access_token);
    },
    // Polling: repeat this request (Runner and CLI) until done() holds or the
    // poll limit passes, then run final() once.
    poll(name, done, final, sinceVar = 'change_at') {
      const n = Number(bru.getVar('poll_n') || 0);
      const since = Number(bru.getVar(sinceVar) || Date.now());
      const waited = (Date.now() - since) / 1000;
      const limit = Number(N.v('poll_limit_seconds') || 660);
      let ok = false;
      try { ok = done(); } catch (e) { ok = false; }
      if (!ok && waited < limit) {
        bru.setVar('poll_n', n + 1);
        console.log(`${name}: not yet after ${Math.round(waited)} s; waiting for the next group sync`);
        bru.runner.setNextRequest(name);
        return;
      }
      bru.setVar('poll_n', 0);
      test(`took ${Math.round(waited)} s, within the 10-minute bound`, () => expect(waited).to.be.below(600));
      final();
    },
    async pollWait() {
      if (Number(bru.getVar('poll_n') || 0) > 0) await bru.sleep(Number(N.v('poll_interval_ms') || 10000));
    },
  };
  return N;
};
